 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Long, predominantly one-color rows/columns are separator bars.
    hbars = []
    for r, row in enumerate(grid):
        counts = Counter(x for x in row if x != 0)
        if counts and max(counts.values()) > w / 2:
            hbars.append(r)
    vbars = []
    for c in range(w):
        counts = Counter(grid[r][c] for r in range(h) if grid[r][c] != 0)
        if counts and max(counts.values()) > h / 2:
            vbars.append(c)

    def keep_indices(size, bars):
        keep = []
        start = 0
        for b in bars:
            if start < b:
                keep.append(start)  # one representative from the blank band
            keep.append(b)
            start = b + 1
        if start < size:
            keep.append(start)
        return keep

    rows = keep_indices(h, hbars)
    cols = keep_indices(w, vbars)
    return [[grid[r][c] for c in cols] for r in rows]
